public class ExchangeRateClient {
    public class ExchangeRateException extends Exception {}

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('quoteCurrencies must not be null or empty.');
        }

        String base = normalizeCurrency(baseCurrency);

        Set<String> quotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            quotes.add(normalizeCurrency(quote));
        }

        HttpRequest request = buildRequest(base, quotes);
        Http http = new Http();
        HttpResponse response = http.send(request);

        if (response.getStatusCode() == 503) {
            response = http.send(request);
        }

        if (response.getStatusCode() != 200) {
            throw new ExchangeRateException(
                'Exchange rate callout failed with HTTP status ' + response.getStatusCode()
            );
        }

        return parseResponse(response.getBody(), quotes);
    }

    private static String normalizeCurrency(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code must not be null.');
        }

        String normalized = code.trim().toUpperCase();
        if (!Pattern.matches('^[A-Z]{3}$', normalized)) {
            throw new ExchangeRateException(
                'Invalid currency code: ' + String.valueOf(code) +
                ' (must be exactly three letters A-Z after trimming).'
            );
        }
        return normalized;
    }

    private static HttpRequest buildRequest(String base, Set<String> quotes) {
        List<String> sortedQuotes = new List<String>(quotes);
        sortedQuotes.sort();
        String symbols = String.join(sortedQuotes, ',');

        String endpoint = 'callout:FB_Exchange_Rates/v1/latest?base=' +
            EncodingUtil.urlEncode(base, 'UTF-8') +
            '&symbols=' + EncodingUtil.urlEncode(symbols, 'UTF-8');

        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        return request;
    }

    private static Map<String, Decimal> parseResponse(String body, Set<String> quotes) {
        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response body.', e);
        }

        Object ratesObject = parsed.get('rates');
        Map<String, Object> rates = null;
        if (ratesObject != null) {
            try {
                rates = (Map<String, Object>) ratesObject;
            } catch (Exception e) {
                throw new ExchangeRateException('Exchange rate response is missing the rates object.');
            }
        }
        if (rates == null) {
            throw new ExchangeRateException('Exchange rate response is missing the rates object.');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();

        for (String code : quotes) {
            if (!rates.containsKey(code)) {
                throw new ExchangeRateException('No exchange rate returned for ' + code + '.');
            }
            try {
                result.put(code, Decimal.valueOf(String.valueOf(rates.get(code))));
            } catch (Exception e) {
                throw new ExchangeRateException('Invalid exchange rate for ' + code + '.', e);
            }
        }

        return result;
    }
}
