public with sharing class ContactLookupAction {

    @InvocableMethod(
        label = 'Find Contact by Email',
        description = 'Finds the earliest created Contact matching the supplied email address.'
    )
    public static List<Result> find(List<Request> requests) {
        Result[] results = new Result[requests.size()];
        for (Integer i = 0; i < requests.size(); i++) {
            results[i] = new Result();
        }

        Map<String, List<Integer>> indicesByEmail = new Map<String, List<Integer>>();
        Set<String> queryEmails = new Set<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            Request req = requests[i];
            String email = (req == null) ? null : req.email;
            if (email != null) {
                email = email.trim();
            }
            if (String.isBlank(email)) {
                continue;
            }

            String key = email.toLowerCase();
            if (!indicesByEmail.containsKey(key)) {
                indicesByEmail.put(key, new List<Integer>());
                queryEmails.add(key);
            }
            indicesByEmail.get(key).add(i);
        }

        if (!queryEmails.isEmpty()) {
            Map<String, Contact> earliestByEmail = new Map<String, Contact>();
            for (Contact c : [
                    SELECT Id, Email, CreatedDate
                    FROM Contact
                    WHERE Email IN :queryEmails
                    ORDER BY CreatedDate ASC
                ]) {
                String key = String.valueOf(c.Email).trim().toLowerCase();
                if (!earliestByEmail.containsKey(key)) {
                    earliestByEmail.put(key, c);
                }
            }

            for (String key : indicesByEmail.keySet()) {
                Contact c = earliestByEmail.get(key);
                Boolean found = c != null;
                Id contactId = found ? c.Id : null;
                for (Integer i : indicesByEmail.get(key)) {
                    results[i] = new Result(contactId, found);
                }
            }
        }

        return results;
    }

    public class Request {
        @InvocableVariable(label = 'Email' required = true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label = 'Contact Id')
        public Id contactId;

        @InvocableVariable(label = 'Found')
        public Boolean found;

        public Result() {}

        public Result(Id contactId, Boolean found) {
            this.contactId = contactId;
            this.found = found;
        }
    }
}
