        assertQuote(0.00, 1,   'DOMESTIC', false, 100);
        assertQuote(0.00, 25,  'DOMESTIC', false, 100.00);

        // Null express is standard, so it still qualifies.
        assertQuote(0.00, 1,   'DOMESTIC', null,  100);

        // Below the threshold is not free.
        assertQuote(5.00, 1,   'DOMESTIC', false, 99.99);

        // Null order value does not qualify.
        assertQuote(5.00, 1,   'DOMESTIC', false, null);

        // Express orders never qualify, even over the threshold.
        assertQuote(7.50, 1,   'DOMESTIC', true,  100);

        // Other zones never qualify, even over the threshold.
        assertQuote(7.00, 1,   'EU', false, 100);
        assertQuote(11.00, 1,  'WORLD', false, 100);
    }

    //----------------------------------------------------------------------
    // Rounding (half up, 2 decimals)
    //----------------------------------------------------------------------
    @isTest
    static void roundingHalfUpTwoDecimals() {
        // Documented example: 21 kg DOMESTIC express = 28.13 (28.125 rounds up).
        assertQuote(28.13, 21, 'DOMESTIC', true, null);

        // 39.375 -> 39.38.
        assertQuote(39.38, 20.1, 'EU', true, null);

        // 42.525 -> 42.53 (distinguishes HALF_UP from HALF_EVEN, which would give 42.52).
        assertQuote(42.53, 22.1, 'EU', true, null);

        // Clean values remain unchanged.
        assertQuote(11.00, 1, 'WORLD', false, null);
        assertQuote(25.20, 20, 'EU', false, null);
    }
