public class OpportunityPipelineHandler {
    public static void handleInsert(List<Opportunity> newOpps) {
        updateOpenPipeline(collectAccountIds(newOpps));
    }

    public static void handleUpdate(List<Opportunity> newOpps, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity newOpp : newOpps) {
            Opportunity oldOpp = oldMap.get(newOpp.Id);
            if (oldOpp == null) {
                continue;
            }

            // Only react when fields that affect the roll-up actually changed.
            if (newOpp.IsClosed != oldOpp.IsClosed
                || newOpp.Amount != oldOpp.Amount
                || newOpp.AccountId != oldOpp.AccountId) {

                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
            }
        }
        updateOpenPipeline(accountIds);
    }

    public static void handleDelete(List<Opportunity> oldOpps) {
        updateOpenPipeline(collectAccountIds(oldOpps));
    }

    public static void handleUndelete(List<Opportunity> newOpps) {
        updateOpenPipeline(collectAccountIds(newOpps));
    }

    private static Set<Id> collectAccountIds(List<Opportunity> opps) {
        Set<Id> accountIds = new Set<Id>();
        if (opps == null) {
            return accountIds;
        }
        for (Opportunity opp : opps) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        return accountIds;
    }

    private static void updateOpenPipeline(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        accountIds.remove(null);
        if (accountIds.isEmpty()) {
            return;
        }

        // Default every affected account to zero so an account with no open
        // opportunities shows 0 and 0 instead of blank.
        Map<Id, Decimal> pipelineByAccount = new Map<Id, Decimal>();
        Map<Id, Integer> countByAccount = new Map<Id, Integer>();
        for (Id accountId : accountIds) {
            pipelineByAccount.put(accountId, 0);
            countByAccount.put(accountId, 0);
        }

        for (AggregateResult result : [
            SELECT AccountId accountId,
                   SUM(Amount) totalAmount,
                   COUNT(Id) openCount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accountId = (Id) result.get('accountId');
            Decimal totalAmount = (Decimal) result.get('totalAmount');
            Integer openCount = (Integer) result.get('openCount');

            pipelineByAccount.put(accountId, totalAmount == null ? 0 : totalAmount);
            countByAccount.put(accountId, openCount);
        }

        // Avoid unnecessary updates. This also breaks recursion with AccountTrigger,
        // which only changes opportunity rating fields and cannot affect pipeline totals.
        Map<Id, Account> existingAccounts = new Map<Id, Account>([
            SELECT Id,
                   FB_Open_Pipeline__c,
                   FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            Decimal newPipeline = pipelineByAccount.get(accountId);
            Integer newCount = countByAccount.get(accountId);
            Account existing = existingAccounts.get(accountId);

            Boolean changed = true;
            if (existing != null) {
                Decimal oldPipeline = existing.FB_Open_Pipeline__c;
                Integer oldCount = existing.FB_Open_Opportunities__c;

                Boolean pipelineUnchanged = (oldPipeline == null && newPipeline == 0)
                    || (oldPipeline != null && oldPipeline == newPipeline);
                Boolean countUnchanged = (oldCount == newCount);

                changed = !(pipelineUnchanged && countUnchanged);
            }

            if (changed) {
                accountsToUpdate.add(new Account(
                    Id = accountId,
                    FB_Open_Pipeline__c = newPipeline,
                    FB_Open_Opportunities__c = newCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
