    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        List<String> fields = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            fields.add(field.getDescribe().getName());
        }
        fields.add('Account.Name');

        String query = 'SELECT ' + String.join(fields, ', ');
        query += ' FROM Opportunity';
        query += ' WHERE AccountId IN :accountIds AND IsClosed = false';
        query += ' ORDER BY Amount DESC NULLS LAST, CloseDate ASC NULLS LAST';
        query += ' LIMIT :maxRecords';

        return (List<Opportunity>) Database.query(query);
    }
}
