        if (String.isBlank(reason)) {
            throw new EscalationException('An escalation reason is required.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        fflib_SObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Boolean escalatedAny = false;

        for (Case c : cases) {
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            Case cUpdate = new Case(Id = c.Id);
            cUpdate.IsEscalated = true;
            cUpdate.Priority = 'High';
            uow.registerDirty(cUpdate);

            Task task = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = Date.today().addDays(1),
                Priority = 'High'
            );
            uow.registerNew(task);

            escalatedAny = true;
        }

        if (escalatedAny) {
            uow.commitWork();
        }
    }
}
