public class ContactPhoneCleanup {
    /**
     * Normalizes the Phone field on the specified Contacts so it contains only digits and '+'.
     *
     * Deviations from the described approach (and why):
     * 1. A contact is added to the update list only when the cleaned Phone differs from the
     *    stored value. This avoids unnecessary DML, reduces trigger invocations, and keeps
     *    the partial-success save results meaningful.
     * 2. Blank phones (null or empty string) are skipped up front, as required.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return failures;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // Single bulk query; safe for up to 200 (or more) IDs in one call.
        for (Contact c : [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds]) {
            String originalPhone = c.Phone;

            // Contacts without a phone are left out.
            if (String.isBlank(originalPhone)) {
                continue;
            }

            // Remove every character that is not a digit or '+'.
            String cleanedPhone = originalPhone.replaceAll('[^0-9+]', '');

            // Only queue records that actually changed.
            if (!originalPhone.equals(cleanedPhone)) {
                contactsToUpdate.add(new Contact(Id = c.Id, Phone = cleanedPhone));
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // allOrNothing = false so one invalid record does not block the rest.
            Database.SaveResult[] saveResults = Database.update(contactsToUpdate, false);

            for (Database.SaveResult saveResult : saveResults) {
                if (!saveResult.isSuccess()) {
                    Database.Error[] errors = saveResult.getErrors();
                    if (errors != null && !errors.isEmpty()) {
                        failures.put(saveResult.getId(), errors[0].getMessage());
                    }
                }
            }
        }

        return failures;
    }
}
