```apex
public class ErpCustomerSync implements Queueable {
    private final List<Id> accountIds;
    private final Integer startIndex;

    // Chunked to stay under the 100 callout-per-transaction limit.
    private static final Integer CHUNK_SIZE = 100;

    public ErpCustomerSync(List<Id> accountIds, Integer startIndex) {
        this.accountIds = accountIds;
        this.startIndex = startIndex;
    }

    public static void enqueue(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }
        List<Id> idList = new List<Id>(accountIds);
        System.enqueueJob(new ErpCustomerSync(idList, 0));
    }

    public void execute(QueueableContext context) {
        Integer endIndex = Math.min(startIndex + CHUNK_SIZE, accountIds.size());
        List<Id> chunk = new List<Id>();
        for (Integer i = startIndex; i < endIndex; i++) {
            chunk.add(accountIds[i]);
        }

        List<Account> accounts = [
            SELECT Id, Name, BillingCountry
            FROM Account
            WHERE Id IN :chunk
            WITH USER_MODE
        ];

        for (Account acc : accounts) {
            sendToErp(acc);
        }

        // Chain the next chunk if any accounts remain.
        if (endIndex < accountIds.size()) {
            System.enqueueJob(new ErpCustomerSync(accountIds, endIndex));
        }
    }

    private static void sendToErp(Account acc) {
        // One customer per JSON array for traceability.
        List<Map<String, Object>> customers = new List<Map<String, Object>>();
        Map<String, Object> customer = new Map<String, Object>();
        customer.put('salesforceId', acc.Id);
        customer.put('name', acc.Name);
        customer.put('country', String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry);
        customers.add(customer);

        String body = JSON.serialize(customers);

        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(body);

        Http http = new Http();
        HttpResponse res = http.send(req);

        // Error handling and retries are out of scope for this ticket.
    }
}
