public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e platform event for each Opportunity.
     *
     * Deviates from the requested per-record EventBus.publish loop: platform events
     * published one-at-a-time with EventBus.publish(SObject) each consume a DML
     * statement, so 200 Opportunities would hit the 150 DML-statement limit
     * (System.LimitException: Too many DML statements). Instead, events are collected
     * into a list and published with a single bulk EventBus.publish(List<SObject>).
     * That call counts as one DML statement regardless of list size (up to 2,000
     * events) and returns Database.SaveResult instances in the same order as the
     * input events, so each result still maps 1:1 to its Opportunity and failures
     * can be identified precisely.
     *
     * @param opportunities Opportunities to publish stage-change events for
     * @return SaveResults in the same order as the input list; an empty list when the
     *         input is null or empty
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        if (opportunities == null || opportunities.isEmpty()) {
            return new List<Database.SaveResult>();
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            Deal_Stage_Change__e event = new Deal_Stage_Change__e();
            event.Opportunity_Id__c = String.valueOf(opp.Id);
            event.Stage__c = opp.StageName;
            event.Amount__c = opp.Amount;
            events.add(event);
        }

        return EventBus.publish(events);
    }
}
