public with sharing class FollowUpTaskService {
    /**
     * Creates a follow-up Task for each Opportunity.
     *
     * Tasks are inserted with Database.insert(tasks, false) so that only one DML
     * statement is used and validation-rule rejections on some Tasks do not prevent
     * the others from being created. The literal per-record try/catch insert pattern
     * cannot be used here: 200 Opportunities would require 200 DML statements,
     * exceeding the 150 DML-statement governor limit.
     *
     * @param opportunityIds Ids of the Opportunities to follow up on.
     * @return Ids of Opportunities whose Task could not be created (empty when all succeed).
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        Set<Id> ids = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                ids.add(opportunityId);
            }
        }

        if (ids.isEmpty()) {
            return failedOpportunityIds;
        }

        Map<Id, Opportunity> opportunityMap = new Map<Id, Opportunity>([
            SELECT Id, OwnerId, Name
            FROM Opportunity
            WHERE Id IN :ids
        ]);

        List<Opportunity> opportunities = new List<Opportunity>();
        List<Task> tasks = new List<Task>();
        Date followUpDate = Date.today().addDays(7);

        for (Id opportunityId : ids) {
            Opportunity opportunity = opportunityMap.get(opportunityId);
            if (opportunity == null) {
                continue;
            }

            opportunities.add(opportunity);
            tasks.add(new Task(
                WhatId       = opportunity.Id,
                OwnerId      = opportunity.OwnerId,
                Subject      = 'Follow up: ' + opportunity.Name,
                ActivityDate = followUpDate,
                Status       = 'Not Started',
                Priority     = 'Normal'
            ));
        }

        if (tasks.isEmpty()) {
            return failedOpportunityIds;
        }

        // allOrNothing = false lets individual Task failures succeed independently.
        Database.SaveResult[] results = Database.insert(tasks, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedOpportunityIds.add(opportunities.get(i).Id);
            }
        }

        return failedOpportunityIds;
    }
}
