public with sharing class LeadContactMatcher {
    /**
     * Matches each Lead to a Contact by email address.
     *
     * @param leads    leads to match; the returned list preserves this order and size
     * @param contacts contacts to search
     * @return a List<Id> the same size as leads. Each element is the Id of the first
     *         contact in contacts whose email matches the lead's email, or null when no
     *         match exists or either email is blank. Matching ignores case and
     *         leading/trailing whitespace. No records are queried or modified.
     */
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        List<Id> matchedIds = new List<Id>();
        if (leads == null) {
            return matchedIds;
        }

        matchedIds = new List<Id>(leads.size());

        // Index contacts by normalized email. This makes the match O(leads + contacts)
        // instead of O(leads * contacts), which keeps the import transaction safely
        // within Apex CPU limits at the described volumes (thousands of rows).
        Map<String, Id> emailToContactId = new Map<String, Id>();
        if (contacts != null) {
            for (Contact contact : contacts) {
                if (contact == null) {
                    continue;
                }
                String normalizedEmail = normalizeEmail(contact.Email);
                if (normalizedEmail != null && !emailToContactId.containsKey(normalizedEmail)) {
                    emailToContactId.put(normalizedEmail, contact.Id);
                }
            }
        }

        for (Lead lead : leads) {
            String normalizedEmail = normalizeEmail(lead == null ? null : lead.Email);
            Id contactId = (normalizedEmail == null) ? null : emailToContactId.get(normalizedEmail);
            matchedIds.add(contactId);
        }

        return matchedIds;
    }

    private static String normalizeEmail(String email) {
        return String.isBlank(email) ? null : email.trim().toLowerCase();
    }
}
