public class RenewalReminderService {

    /**
     * Sends a renewal reminder email to the owner of each opportunity.
     *
     * Implementation notes:
     * - The request asked for one Messaging.sendEmail call per opportunity inside
     *   the loop so that a single failure would not stop the others. That is a bad
     *   idea at batch size: Apex allows only 10 sendEmail invocations per
     *   transaction, so looping over 200 opportunities throws
     *   "Too many Email Invocations" and aborts the entire job.
     * - Instead, every message is built in the loop and submitted in a single
     *   Messaging.sendEmail call (one invocation, safely under the limit even for
     *   200 opportunities). Fault isolation is still provided by checking each
     *   SendEmailResult individually and counting only the successes, so one bad
     *   recipient does not prevent the others from being sent.
     * - Emails addressed to Users with setTargetObjectId do not consume the org's
     *   daily external email allocation.
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // De-duplicate in case the caller passes the same Id more than once.
        Set<Id> uniqueIds = new Set<Id>(opportunityIds);

        // One bulk SOQL query outside the loop.
        List<Opportunity> opportunities = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueIds
        ];

        List<Messaging.SingleEmailMessage> emails = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : opportunities) {
            // An Opportunity can be owned by a User or a Queue. setTargetObjectId
            // accepts only User, Contact, or Lead Ids.
            if (opp.OwnerId == null || opp.OwnerId.getSObjectType() != User.sObjectType) {
                continue;
            }

            if (opp.CloseDate == null) {
                continue;
            }

            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody(
                'Renewal reminder for opportunity "' + opp.Name + '". ' +
                'The close date is ' + opp.CloseDate.format() + '.'
            );
            emails.add(email);
        }

        if (emails.isEmpty()) {
            return 0;
        }

        // A single invocation for the whole batch keeps us under the
        // 10 sendEmail-invocations-per-transaction governor limit.
        Messaging.SendEmailResult[] results = Messaging.sendEmail(emails);

        Integer sentSuccessfully = 0;
        for (Messaging.SendEmailResult result : results) {
            if (result != null && result.isSuccess()) {
                sentSuccessfully++;
            }
        }

        return sentSuccessfully;
    }
}
