    'Account.Name',
    'Account.Industry',
    'Account.AnnualRevenue',
    'Account.Owner.Name'
];

export default class AccountHeader extends LightningElement {
    @api recordId;

    @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
    account;

    get isLoading() {
        return !this.account?.data && !this.account?.error;
    }

    get error() {
        return this.account?.error;
    }

    get data() {
        return this.account?.data;
    }

    get name() {
        return this.account?.data?.fields?.Name?.value;
    }

    get industry() {
        return this.account?.data?.fields?.Industry?.value;
    }

    get annualRevenue() {
        return this.account?.data?.fields?.AnnualRevenue?.value;
    }

    get ownerName() {
        const field = this.account?.data?.fields?.Owner;
        if (!field) {
            return undefined;
        }
        const { value, displayValue } = field;
        if (value && typeof value === 'object') {
            return value.Name;
        }
        return displayValue ?? value;
    }
}
