    }

    /**
     * Ensures every request ends up with exactly one partial soft credit of the given
     * amount on the opportunity, linked to the contact's OpportunityContactRole whose
     * Role equals request.role.
     *
     * The whole call is validated before any DML. If any request is invalid, a
     * SoftCreditException is thrown and nothing is changed.
     *
     * Bulk-safe: at most 4 SOQL queries and 4 DML statements per call.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest request : requests) {
            if (request != null) {
                if (request.opportunityId != null) {
                    opportunityIds.add(request.opportunityId);
                }
                if (request.contactId != null) {
                    contactIds.add(request.contactId);
                }
            }
        }

        // Query 1 of 4: opportunity amount and primary contact.
        Map<Id, Opportunity> opportunityById = new Map<Id, Opportunity>();
        if (!opportunityIds.isEmpty()) {
            for (Opportunity opportunity : [
                    SELECT Id, Amount, npsp__Primary_Contact__c
                    FROM Opportunity
                    WHERE Id IN :opportunityIds
                ]) {
                opportunityById.put(opportunity.Id, opportunity);
            }
        }

        // Query 2 of 4: contact existence and name.
        Map<Id, Contact> contactById = new Map<Id, Contact>();
        if (!contactIds.isEmpty()) {
            for (Contact contact : [SELECT Id, Name FROM Contact WHERE Id IN :contactIds]) {
                contactById.put(contact.Id, contact);
            }
        }

        // Query 3 of 4: existing contact roles on the affected opportunities/contacts.
        Map<String, List<OpportunityContactRole>> contactRolesByPair =
            new Map<String, List<OpportunityContactRole>>();
        if (!opportunityIds.isEmpty() && !contactIds.isEmpty()) {
            for (OpportunityContactRole contactRole : [
                    SELECT Id, OpportunityId, ContactId, Role
                    FROM OpportunityContactRole
                    WHERE OpportunityId IN :opportunityIds
                      AND ContactId IN :contactIds
                ]) {
                String key = pairKey(contactRole.OpportunityId, contactRole.ContactId);
                if (!contactRolesByPair.containsKey(key)) {
                    contactRolesByPair.put(key, new List<OpportunityContactRole>());
                }
                contactRolesByPair.get(key).add(contactRole);
            }
        }

        // Query 4 of 4: existing partial soft credits on the affected opportunities/contacts.
        Map<String, List<npsp__Partial_Soft_Credit__c>> softCreditsByPair =
            new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        if (!opportunityIds.isEmpty() && !contactIds.isEmpty()) {
            for (npsp__Partial_Soft_Credit__c softCredit : [
                    SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                           npsp__Role_Name__c, npsp__Contact_Role_ID__c
                    FROM npsp__Partial_Soft_Credit__c
                    WHERE npsp__Opportunity__c IN :opportunityIds
                      AND npsp__Contact__c IN :contactIds
                ]) {
                String key = pairKey(softCredit.npsp__Opportunity__c, softCredit.npsp__Contact__c);
                if (!softCreditsByPair.containsKey(key)) {
                    softCreditsByPair.put(key, new List<npsp__Partial_Soft_Credit__c>());
                }
                softCreditsByPair.get(key).add(softCredit);
            }
        }

        // ------------------------------------------------------------------
        // Validate every request before any DML runs. If anything is invalid,
        // throw and nothing is changed.
        // ------------------------------------------------------------------
        List<String> validationErrors = new List<String>();
        for (SoftCreditRequest request : requests) {
            if (request == null) {
                validationErrors.add('Request cannot be null.');
                continue;
            }
            if (request.opportunityId == null) {
                validationErrors.add('Opportunity ID is required.');
                continue;
            }
            if (request.contactId == null) {
                validationErrors.add('Contact ID is required.');
                continue;
            }

            Opportunity opportunity = opportunityById.get(request.opportunityId);
            if (opportunity == null) {
                validationErrors.add('Opportunity ' + request.opportunityId + ' was not found.');
                continue;
            }

            Contact contact = contactById.get(request.contactId);
            if (contact == null) {
                validationErrors.add('Contact ' + request.contactId + ' was not found.');
                continue;
            }

            if (request.contactId == opportunity.npsp__Primary_Contact__c) {
                validationErrors.add(
                    'Contact ' + request.contactId + ' is the primary contact of opportunity ' +
                    request.opportunityId + ' and cannot receive a partial soft credit.'
                );
                continue;
            }

            if (request.amount == null) {
                validationErrors.add(
                    'Amount is required for contact ' + request.contactId + ' on opportunity ' +
                    request.opportunityId + '.'
                );
                continue;
            }

            Decimal opportunityAmount = opportunity.Amount == null ? 0 : opportunity.Amount;
            if (request.amount <= 0) {
                validationErrors.add(
                    'Amount must be greater than zero for contact ' + request.contactId +
                    ' on opportunity ' + request.opportunityId + '.'
                );
                continue;
            }
            if (request.amount > opportunityAmount) {
                validationErrors.add(
                    'Amount ' + request.amount + ' exceeds the opportunity amount ' +
                    opportunityAmount + ' for opportunity ' + request.opportunityId + '.'
                );
            }
        }

        if (!validationErrors.isEmpty()) {
            throw new SoftCreditException(String.join(validationErrors, '; '));
        }

        // ------------------------------------------------------------------
        // Give the contact exactly one contact role on the opportunity whose
        // Role matches the request. Reuse an existing role (updating its Role
        // when necessary), otherwise insert a new one. Remove duplicates so the
        // contact never ends up with more than one role on the opportunity.
        // ------------------------------------------------------------------
        List<OpportunityContactRole> contactRolesToUpsert =
            new List<OpportunityContactRole>();
        List<OpportunityContactRole> duplicateContactRolesToDelete =
            new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> pairToContactRole =
            new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            List<OpportunityContactRole> existingRoles = contactRolesByPair.get(key);
            OpportunityContactRole contactRole;

            if (existingRoles == null || existingRoles.isEmpty()) {
                contactRole = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role
                );
                contactRolesToUpsert.add(contactRole);
            } else {
                contactRole = existingRoles.get(0);
                if (contactRole.Role != request.role) {
                    contactRole.Role = request.role;
                    contactRolesToUpsert.add(contactRole);
                }
                for (Integer i = 1; i < existingRoles.size(); i++) {
                    duplicateContactRolesToDelete.add(existingRoles.get(i));
                }
            }
            pairToContactRole.put(key, contactRole);
        }

        // DML 1 of 4: insert or update contact roles.
        if (!contactRolesToUpsert.isEmpty()) {
            upsert contactRolesToUpsert;
        }

        // DML 2 of 4: delete duplicate contact roles.
        if (!duplicateContactRolesToDelete.isEmpty()) {
            delete duplicateContactRolesToDelete;
        }

        // Map each (opportunity, contact) pair to its contact role ID. Newly
        // inserted roles have their ID populated by the upsert above.
        Map<String, Id> pairToContactRoleId = new Map<String, Id>();
        for (String key : pairToContactRole.keySet()) {
            pairToContactRoleId.put(key, pairToContactRole.get(key).Id);
        }

        // ------------------------------------------------------------------
        // Prepare partial soft credits: update the existing one for the pair,
        // otherwise insert a new one linked to the contact role. Remove any
        // duplicates so there is never more than one soft credit per pair.
        // ------------------------------------------------------------------
        List<npsp__Partial_Soft_Credit__c> softCreditsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> duplicateSoftCreditsToDelete =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : requests) {
            String key = pairKey(request.opportunityId, request.contactId);
            Id contactRoleId = pairToContactRoleId.get(key);
            List<npsp__Partial_Soft_Credit__c> existingSoftCredits = softCreditsByPair.get(key);
            npsp__Partial_Soft_Credit__c softCredit;

            if (existingSoftCredits == null || existingSoftCredits.isEmpty()) {
                softCredit = new npsp__Partial_Soft_Credit__c();
                softCredit.npsp__Opportunity__c = request.opportunityId;
                softCredit.npsp__Contact__c = request.contactId;
                softCredit.npsp__Amount__c = request.amount;
                softCredit.npsp__Role_Name__c = request.role;
                softCredit.npsp__Contact_Role_ID__c = String.valueOf(contactRoleId);
                softCreditsToUpsert.add(softCredit);
            } else {
                softCredit = existingSoftCredits.get(0);
                softCredit.npsp__Amount__c = request.amount;
                softCredit.npsp__Role_Name__c = request.role;
                softCredit.npsp__Contact_Role_ID__c = String.valueOf(contactRoleId);
                softCreditsToUpsert.add(softCredit);
                for (Integer i = 1; i < existingSoftCredits.size(); i++) {
                    duplicateSoftCreditsToDelete.add(existingSoftCredits.get(i));
                }
            }
        }

        // DML 3 of 4: insert or update partial soft credits.
        if (!softCreditsToUpsert.isEmpty()) {
            upsert softCreditsToUpsert;
        }

        // DML 4 of 4: delete duplicate partial soft credits.
        if (!duplicateSoftCreditsToDelete.isEmpty()) {
            delete duplicateSoftCreditsToDelete;
        }
    }
}
