public with sharing class ContactImportService {
    private class ContactImportServiceException extends Exception {}

    /**
     * TAF action type (Apex class) that creates the "Send welcome pack" Task after
     * a Contact is inserted. The Trigger Actions Framework is installed as an
     * unlocked package with no namespace, so the class is resolved by its simple
     * name rather than a hard compile-time reference.
     */
    private static final System.Type WELCOME_TASK_ACTION_TYPE =
        Type.forName('TA_Contact_CreateWelcomeTask');

    /**
     * Imports legacy contacts in a single DML statement.
     *
     * The TAF welcome-task action is bypassed for the duration of the insert so
     * existing customers do not receive a welcome task. Phone formatting and all
     * other Contact automation (e.g. TA_Contact_FormatPhone) still run.
     *
     * The bypass is cleared in a finally block, so it never leaks beyond this
     * method: contacts inserted later in the same transaction receive their
     * welcome task as usual.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        if (WELCOME_TASK_ACTION_TYPE == null) {
            throw new ContactImportServiceException(
                'ContactImportService: unable to resolve TAF action type ' +
                'TA_Contact_CreateWelcomeTask. Confirm the action class is deployed.'
            );
        }

        // Bypass only the welcome-task action. All other Contact automation
        // continues to run during the insert below.
        MetadataTriggerHandler.bypass(WELCOME_TASK_ACTION_TYPE);

        try {
            insert contacts;
        } finally {
            // Always remove the bypass, even if the DML fails.
            MetadataTriggerHandler.clearBypass(WELCOME_TASK_ACTION_TYPE);
        }
    }
}
