public with sharing class AccountOwnershipService {
    /**
     * Reassigns the given Accounts (and their Contacts) to a new owner.
     *
     * All Account trigger actions are bypassed for the duration of the ownership
     * change; Contact trigger actions run normally. The Account bypass is cleared
     * in a finally block so Account automation behaves normally for the rest of
     * the transaction, whether this method succeeds or throws.
     *
     * @param accountIds  Accounts to reassign (up to 200).
     * @param newOwnerId  New owner User Id.
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        Set<Id> ids = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                ids.add(accountId);
            }
        }
        if (ids.isEmpty()) {
            return;
        }

        // Bypass every Account trigger action for the whole ownership change.
        TriggerBase.bypass(Account.sObjectType);

        try {
            // 1 SOQL: the Accounts being reassigned.
            List<Account> accounts = [
                SELECT Id, OwnerId
                FROM Account
                WHERE Id IN :ids
            ];
            // 2 SOQL: the Contacts on those Accounts.
            List<Contact> contacts = [
                SELECT Id, OwnerId
                FROM Contact
                WHERE AccountId IN :ids
            ];

            List<Account> accountsToUpdate = new List<Account>();
            for (Account a : accounts) {
                if (a.OwnerId != newOwnerId) {
                    a.OwnerId = newOwnerId;
                    accountsToUpdate.add(a);
                }
            }

            List<Contact> contactsToUpdate = new List<Contact>();
            for (Contact c : contacts) {
                if (c.OwnerId != newOwnerId) {
                    c.OwnerId = newOwnerId;
                    contactsToUpdate.add(c);
                }
            }

            // All-or-none DML; exceptions propagate to the caller unchanged.
            if (!accountsToUpdate.isEmpty()) {
                Database.update(accountsToUpdate, true);
            }
            if (!contactsToUpdate.isEmpty()) {
                Database.update(contactsToUpdate, true);
            }
        } finally {
            // Restore normal Account automation for the remainder of the transaction.
            TriggerBase.clearBypass(Account.sObjectType);
        }
    }
}
