public with sharing class TA_Opportunity_CollectForErpSync
        implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    // Accumulates Opportunity Ids that require ERP sync for the current DML operation.
    // Being static, it survives the trigger chunks of a single DML statement (e.g. 200 + 50),
    // so we can build one queueable job per DML operation instead of one per chunk.
    private static Set<Id> opportunityIdsToSync = new Set<Id>();

    public void afterInsert(List<SObject> triggerNew) {
        // Newly created Opportunities always need to be pushed to the ERP.
        for (SObject record : triggerNew) {
            opportunityIdsToSync.add(((Opportunity) record).Id);
        }
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        // Only Opportunities whose StageName changed need to be pushed to the ERP.
        Map<Id, Opportunity> oldOpportunitiesById = new Map<Id, Opportunity>();
        for (SObject oldRecord : triggerOld) {
            Opportunity oldOpportunity = (Opportunity) oldRecord;
            oldOpportunitiesById.put(oldOpportunity.Id, oldOpportunity);
        }

        for (SObject newRecord : triggerNew) {
            Opportunity newOpportunity = (Opportunity) newRecord;
            Opportunity oldOpportunity = oldOpportunitiesById.get(newOpportunity.Id);
            if (oldOpportunity != null && newOpportunity.StageName != oldOpportunity.StageName) {
                opportunityIdsToSync.add(newOpportunity.Id);
            }
        }
    }

    // Returns the collected Ids and resets the accumulator for the next DML operation.
    public static Set<Id> getAndClearCollectedIds() {
        Set<Id> collectedIds = opportunityIdsToSync;
        opportunityIdsToSync = new Set<Id>();
        return collectedIds;
    }
}
