public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String DUPLICATE_EMAIL_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = new List<Contact>();
        for (SObject s : triggerNew) {
            contacts.add((Contact) s);
        }
        evaluate(contacts, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> changedNew = new List<Contact>();
        Map<Id, Contact> changedOld = new Map<Id, Contact>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Contact neu = (Contact) triggerNew[i];
            Contact prev = (Contact) triggerOld[i];
            if (neu.AccountId != prev.AccountId || neu.Email != prev.Email) {
                changedNew.add(neu);
                changedOld.put(neu.Id, prev);
            }
        }
        evaluate(changedNew, changedOld);
    }

    private static void evaluate(List<Contact> triggerNew, Map<Id, Contact> triggerOld) {
        List<Contact> candidates = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact c : triggerNew) {
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }
            candidates.add(c);
            accountIds.add(c.AccountId);
            emails.add(c.Email.toLowerCase());
        }

        if (candidates.isEmpty()) {
            return;
        }

        Set<Id> excludeIds = (triggerOld == null) ? new Set<Id>() : triggerOld.keySet();

        Map<String, Contact> existingByKey = new Map<String, Contact>();
        for (Contact c : [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE IsDeleted = false
                  AND Id NOT IN :excludeIds
                  AND AccountId IN :accountIds
                  AND Email IN :emails
        ]) {
            existingByKey.put(key(c.AccountId, c.Email), c);
        }

        Set<String> seenInThisSave = new Set<String>();
        for (Contact c : candidates) {
            String k = key(c.AccountId, c.Email);
            if (existingByKey.containsKey(k) || seenInThisSave.contains(k)) {
                c.addError(DUPLICATE_EMAIL_MESSAGE);
            } else {
                seenInThisSave.add(k);
            }
        }
    }

    private static String key(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }
}
