public inherited sharing class TA_Case_RollupOpenCount
    implements TriggerAction.AfterInsert,
               TriggerAction.AfterUpdate,
               TriggerAction.AfterDelete,
               TriggerAction.AfterUndelete {

    /**
     * After insert: a new Case may open on an Account, so refresh that Account's
     * open Case count. Cases without an Account are ignored.
     */
    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Case c = (Case) record;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        refreshOpenCaseCounts(accountIds);
    }

    /**
     * After update: a Case may open or close, or move between Accounts. Refresh the
     * open Case count on both the prior and current Account.
     */
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];
            if (newCase.AccountId != null) {
                accountIds.add(newCase.AccountId);
            }
            if (oldCase.AccountId != null) {
                accountIds.add(oldCase.AccountId);
            }
        }
        refreshOpenCaseCounts(accountIds);
    }

    /**
     * After delete: removing a Case can lower an Account's open Case count,
     * possibly to zero.
     */
    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerOld) {
            Case c = (Case) record;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        refreshOpenCaseCounts(accountIds);
    }

    /**
     * After undelete: a restored Case may reopen on an Account.
     */
    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Case c = (Case) record;
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        refreshOpenCaseCounts(accountIds);
    }

    /**
     * Recompute FB_Open_Case_Count__c for every affected Account.
     *
     * Bulk safety: one aggregate SOQL query and one DML update, no matter how
     * many Cases are in the trigger execution (e.g. 200 per operation).
     * Accounts with no open Cases are written with 0, never left blank.
     */
    private void refreshOpenCaseCounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCaseCountByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId accountId, COUNT(Id) openCount
            FROM Case
            WHERE IsClosed = false
              AND AccountId IN :accountIds
            GROUP BY AccountId
        ]) {
            openCaseCountByAccount.put(
                (Id) ar.get('accountId'),
                (Integer) ar.get('openCount')
            );
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            Integer openCount = openCaseCountByAccount.get(accountId);
            if (openCount == null) {
                openCount = 0;
            }
            accountsToUpdate.add(
                new Account(Id = accountId, FB_Open_Case_Count__c = openCount)
            );
        }

        update accountsToUpdate;
    }
}
