public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    private static Boolean hasRun = false;

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        if (hasRun || triggerNew == null || triggerOld == null) {
            return;
        }
        hasRun = true;

        List<Task> tasks = new List<Task>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            if (amountChanged(triggerOld[i].Amount, triggerNew[i].Amount)) {
                tasks.add(new Task(
                    WhatId = triggerNew[i].Id,
                    Subject = 'Amount changed',
                    Status = 'Completed'
                ));
            }
        }

        if (!tasks.isEmpty()) {
            insert tasks;
        }
    }

    private static Boolean amountChanged(Decimal oldVal, Decimal newVal) {
        if (oldVal == null && newVal == null) {
            return false;
        }
        if (oldVal == null || newVal == null) {
            return true;
        }
        return oldVal != newVal;
    }
}
